\addplot[curveBlue,thick,<->,domain=2.53:5.7] {-3/(x-2)+1};
\addplot[curveBlue,only marks,mark=*] coordinates {(3,-2)};
\node[anchor=north west,font=\fontsize{10}{12}\selectfont,text=black] at (axis cs:3,-2) {$(3,-2)$};
\node[anchor=north west,font=\fontsize{10}{12}\selectfont,text=black] at (axis cs:2,5.8) {$x=2$};
\node[anchor=south east,font=\fontsize{10}{12}\selectfont,text=black] at (axis cs:5.8,1) {$y=1$};
